#include <atomic>
#include <iostream>
#include <mutex>
#include <thread>
int main(){int iterations{};std::cin>>iterations;int left=100;int right=100;std::mutex leftMutex;std::mutex rightMutex;std::atomic<bool> start{false};std::atomic<int> completed{0};auto transfer=[&](bool forward){while(!start.load(std::memory_order_acquire))std::this_thread::yield();for(int index=0;index<iterations;++index){std::scoped_lock lock(leftMutex,rightMutex);if(forward&&left>0){--left;++right;}else if(!forward&&right>0){--right;++left;}completed.fetch_add(1,std::memory_order_relaxed);}};std::thread first(transfer,true);std::thread second(transfer,false);start.store(true,std::memory_order_release);first.join();second.join();std::cout<<"total="<<left+right<<" completed="<<completed.load()<<"\n";}

